"""Generates supabase/seed.sql from the Bar and Floor lists (the printed inventory sheets)."""
from pathlib import Path

BAR = [
 ("Tequila","bottle",["Corazón Blanco","Corazón Añejo","House Spicy Tequila (infused)","Teremana Blanco","Teremana Reposado","Centenario Plata","Herradura Blanco","Herradura Reposado","Suerte Reposado","Suerte Añejo","Don Julio Blanco","Don Julio Reposado","Don Julio Añejo","Patrón Silver","Patrón Reposado","Patrón Añejo","Casamigos Blanco","Casamigos Reposado","Grand Mayan Triple Distilled","Grand Mayan Reposado","Grand Mayan Extra Aged","Dobel Cristalino","Komos Añejo Reserva","Don Fulano Reposado","Reserva de la Familia","Rey Sol Extra Añejo","Siete Leguas Extra Añejo"]),
 ("Mezcal","bottle",["Bozal Espadín","Bozal Jamón Ibérico","Bozal Tobasiche","Bozal Chino Verde","Los Vecinos Mezcal"]),
 ("Vodka","bottle",["Wheatley Vodka","Tito's Handmade","Ketel One","Leopold's Silver Tree","Grey Goose"]),
 ("Gin","bottle",["Denver Dry Gin","Tanqueray","Bombay Sapphire","Hendrick's","Roku Japanese Gin"]),
 ("Bourbon","bottle",["Jack Daniel's Old No. 7","Weller Special Reserve","Bulleit Bourbon","Buffalo Trace","Wild Turkey 101","Blade & Bow","Eagle Rare 10","Woodford Reserve","Woodford Reserve Dbl. Oaked","Stranahan's Blue Peak","Maker's Mark","Basil Hayden","Elijah Craig 12","Elijah Craig Barrel Proof","Laws Four Grain","Henry McKenna Sgl. Barrel 10","Five Trail Cask Finish","Five Trail Barrel Proof","E.H. Taylor Small Batch","Blanton's Single Barrel","Angel's Envy"]),
 ("Rye / Irish / Scotch","bottle",["Bulleit Rye 95","Jameson Irish Whiskey","The Balvenie"]),
 ("Single Malt","bottle",["American Single Malt","Virginia Highland","Courage & Conviction"]),
 ("Canadian / Flavored Whiskey","bottle",["Seagram's 7 Crown","Crown Royal Fine Deluxe","Crown Royal Apple","Crown Royal Blackberry","Fireball Apple"]),
 ("Rum","bottle",["Bacardi Superior","Captain Morgan Spiced","Malibu Coconut","RumChata"]),
 ("Liqueurs, Cordials + Brandy","bottle",["Hennessy VS Cognac","Sweet Vermouth","Dry Vermouth","Aperol","Campari","Amaro Nonino","Jägermeister","Banana Liqueur","Chocolate Liqueur","Crème de Cacao","Kahlúa","Baileys Irish Cream","Frangelico","Chambord","St. Germain","Grand Gala","Grand Marnier","Peach Schnapps"]),
 ("Juices + Mixers","bottle",["Lime Juice","Lemon Juice","Cranberry Juice","Pineapple Juice","Orange Juice","Passion Fruit Purée","Bloody Mary Mix","Grapefruit Soda","Ginger Beer","Club Soda","Tonic Water"]),
 ("Syrups + Bitters","bottle",["Simple Syrup","Agave Nectar","Grenadine","Orgeat","Honey","Angostura Bitters","Orange Bitters","Chocolate Bitters"]),
 ("Fresh / Garnish",None,[("Limes","case"),("Lemons","case"),("Oranges","case"),("Strawberries","pack"),("Blackberries","pack"),("Eggs (egg white)","dozen"),("Cocktail Cherries","jar"),("Olives","jar"),("Celery","bunch"),("Cinnamon Sticks","pack"),("Salt (rim)","container"),("Sugar (rim)","container")]),
]
FLOOR = [
 ("To-Go",None,[("To-Go Bag – Paper Bag","pack"),("To-Go Bag – Plastic Bag","pack"),("To-Go Cutlery Set","case"),("Portion Cups","sleeve")]),
 ("Cups + Straws",None,[("Plastic Cups","sleeve"),("Plastic Cup Lids","sleeve"),("Straws","box"),("Cocktail Straws","box")]),
 ("Beverage",None,[("Iced Tea","bag"),("Hot Teas","box")]),
 ("Paper + Service",None,[("Paper Napkins","pack"),("Bar Napkins","pack"),("Paper Towels","roll"),("Gloves","box"),("Toilet Paper","roll")]),
 ("Cleaning Supplies","bottle",["Glass Cleaner","Multi-Surface Cleaner"]),
]

q = lambda s: "'" + s.replace("'", "''") + "'"
out = ["-- Generated by scripts/make_seed.py — Bar and Floor starting lists", "begin;", ""]
n = 0
for area, groups in (("bar", BAR), ("floor", FLOOR)):
    for ci, (cat, unit, items) in enumerate(groups, 1):
        rows = []
        for ii, it in enumerate(items, 1):
            name, u = (it if isinstance(it, tuple) else (it, unit))
            rows.append(f"  ({q(name)}, {q(u)}, {ii * 10})")
            n += 1
        out.append(f"with c as (insert into public.categories (area, name, sort_order) values ({q(area)}, {q(cat)}, {ci * 10}) returning id)")
        out.append("insert into public.items (category_id, name, unit, sort_order)")
        out.append("select c.id, v.name, v.unit, v.sort_order from c, (values")
        out.append(",\n".join(rows))
        out.append(") as v(name, unit, sort_order);\n")
out.append("commit;")
Path(__file__).resolve().parent.parent.joinpath("supabase", "seed.sql").write_text("\n".join(out) + "\n", encoding="utf-8")
print(f"{n} items written")
